// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        address owner = address(0x1);
        vm.prank(owner);
        c.initialize();
        vm.prank(owner);
        bool ok;
        try c.updateRoundImplementation(payable(address(0))) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "updateRoundImplementation to zero should revert");
    }
}
